from sqlalchemy.ext.asyncio import AsyncSession
import uuid
from app.models.experiment import Experiment

async def create_experiment_from_ai(
    db: AsyncSession,
    user_id: uuid.UUID,
    reflection_id: uuid.UUID | None,
    suggestion: str,
    category: str | None = None,
) -> Experiment:
    """Create an experiment suggestion generated by AI for a user."""
    experiment = Experiment(
        user_id=user_id,
        reflection_id=reflection_id,
        description=suggestion,
        category=category,
        status="pending",
    )
    db.add(experiment)
    await db.commit()
    await db.refresh(experiment)
    return experiment
